example:
capability Renderer = Container @build("containers/renderer") @port(8080)

service api from http {
    on GET("/render/:tenant") (tenant: String) -> Effect[HttpResult[String]] by Visitor given Renderer {
        let res <- Renderer.send("tenant-\(tenant)", req)   // ⚠ any caller picks the instance
        …
    }
}

service api from http {
    on GET("/render") () -> Effect[HttpResult[String]] by m: Member given Renderer {
        let res <- Renderer.send(m.identity, req)       // ✓ the authenticated identity chooses
        …
    }
}
